import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        t_str = next(iterator)
        t = int(t_str)
    except StopIteration:
        return

    output_lines = []

    for _ in range(t):
        try:
            n = int(next(iterator))
            m = int(next(iterator))
        except StopIteration:
            break

        adj = [[] for _ in range(n + 1)]

        for _ in range(m):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)

        result = [0] * (n + 1)

        if n == 0:
            output_lines.append("")
            continue

        result[1] = 1

        q = deque([1])
        visited = [False] * (n + 1)
        visited[1] = True

        while q:
            u = q.popleft()

            if result[u] == -1:
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        result[v] = -1
                        q.append(v)
                    elif result[v] != -1:
                        result[v] = -1
                        q.append(v)
                continue

            cnt = 0
            for v in adj[u]:
                if result[u] == 1:
                    cnt += 1
                elif result[u] == 2:
                    cnt += 2
                elif result[u] == -1:
                    cnt = 2
                    break

            if cnt >= 2:
                current_status = 2
            else:
                current_status = cnt

            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    result[v] = current_status
                    q.append(v)
                else:
                    if result[v] == -1:
                        pass
                    elif result[v] == 0:
                        result[v] = current_status
                        q.append(v)
                    elif result[v] == 1:
                        if current_status == 1:
                            result[v] = 2
                            q.append(v)
                        elif current_status == 2:
                            result[v] = 2
                            q.append(v) 
                        elif current_status == -1:
                            result[v] = -1
                            q.append(v)
                    elif result[v] == 2:
                        if current_status == 1:
                            pass
                        elif current_status == 2:
                            pass
                        elif current_status == -1:
                            result[v] = -2
                            q.append(v)

        ans = []
        for i in range(1, n + 1):
            if result[i] == -2:
                ans.append(-1)
            else:
                ans.append(result[i])

        output_lines.append(" ".join(map(str, ans)))

    print("\n".join(output_lines))

if __name__ == "__main__":
    solve()
